#[cfg(verus_keep_ghost)]
impl<K, V, Pred> !Sync for LocalInvariant<K, V, Pred> {}

macro_rules! declare_invariant_impl {
    ($invariant:ident => $selfid:ident => $($into_inner_clause:tt)*) => {
